import{z as s,x as r,o as a,c as B,q as E,j as t,D as o,d,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"clone 标志","description":"","frontmatter":{"title":"clone 标志","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clone-flags.md","filePath":"cs/clone-flags.md","lastUpdated":1791413859000}'),A={name:"cs/clone-flags.md"};function i(_,e,C,p,m,h){const c=r("Mermaid");return a(),B("div",null,[e[2]||(e[2]=E('<h1 id="clone-标志" tabindex="-1">clone 标志 <a class="header-anchor" href="#clone-标志" aria-label="Permalink to &quot;clone 标志&quot;">​</a></h1><div class="epigraph"><p>fork 是一份固定的共享清单；clone 用标志位选择与父共享地址空间、文件表还是命名空间，从而把进程和线程做成同一原语的两端。</p><footer>—— 据 Love, Linux Kernel Development；Bovet and Cesati 整理</footer></div><p><a href="/cs/thread-tls">上一课</a>给出每线程 TLS。<a href="/cs/fork">fork</a> 几乎复制一切（文件表除外常共享引用）。缺口是更细的创建：<strong>clone</strong>——调用者选择与父共享 <code>mm</code>、文件、信号、命名空间中的哪几项。POSIX 线程创建在 Linux 上就是带 <code>CLONE_VM</code> 等标志的 clone。本课只钉标志的语义轴，不把每个 <code>CLONE_*</code> 位背完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若内核同时维持 <code>fork</code> 与 <code>thread_create</code> 两套完全不同的路径，共享与复制规则会分叉。统一成 clone：新 PCB 必有，标志决定指针是共享还是深拷。<code>CLONE_VM</code>：同页表，即线程。不设：新地址空间，即进程。<code>CLONE_FILES</code>：同文件表。缺口不是 TLS 布局，而是这份<strong>资源共享菜单</strong>。<span class="marginnote">直觉类比「共享还是深拷」：fork 像把整本通讯录复印一份，之后各写各的互不影响；带 <code>CLONE_VM</code> 的 clone 像两人合看同一本——一方改了另一方立刻看见。每个标志都在回答同一个问题：这一项是「指过去」还是「抄一份」。</span></p><p><span class="marginnote">命名空间标志（PID、mount、net）把「容器」做成 clone 的极端：看起来像进程，看见的是另一套名字。隔离策略是更后的课，本课只承认位存在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>系统调用：分配 PCB 与内核栈，按位挂接或复制 <code>mm</code>、<code>fs</code>、<code>files</code>、<code>sighand</code>。父与子的返回值约定类似 fork（或通过ptid/ctid 写出 tid）。用户库把「创建线程」译成一组固定位 + 新栈 + 新 TLS。错误则不留下半共享的对象。<span class="marginnote">数字实例：这些标志就是 32 位整数里的各个比特——<code>CLONE_VM</code> 是第 8 位（0x100）、<code>CLONE_FILES</code> 是第 10 位（0x400）、<code>CLONE_THREAD</code> 是第 16 位（0x10000）。一次调用把想要的位按位或起来传进去，内核逐位决定「共享谁、复制谁」。</span></p>',8)),(a(),t(l,null,{default:o(()=>[n(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22clone%22%5D%20--%3E%20VM%5B%22CLONE_VM%3A%20%E5%85%B1%E4%BA%AB%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20CL%20--%3E%20FIL%5B%22CLONE_FILES%3A%20%E5%85%B1%E4%BA%AB%E6%96%87%E4%BB%B6%E8%A1%A8%22%5D%0A%20%20CL%20--%3E%20NEW%5B%22%E6%97%A0%E6%A0%87%E5%BF%97%3A%20%E6%96%B0%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<p>与<a href="/cs/process-groups">进程组</a>的交界：线程组（<code>CLONE_THREAD</code>）共享 TGID，wait 的是组而不是每个 tid——点到即可。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>标志把「进程 vs 线程」从类型变成配置。调度器仍看见一个个 <code>task_struct</code>；是否换页表根在切换时看 <code>mm</code> 指针是否相同。用户若错误组合（共享 vm 却不共享信号手），语义古怪，库不会那样做。主干只要求：共享 vm ⇒ 同进程线程模型。</p>',3)),(a(),t(l,null,{default:o(()=>[n(c,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22clone%20%E5%88%9B%E5%BB%BA%E6%96%B0%20task_struct%22%5D%20--%3E%20Q%7B%22%E9%A1%B5%E8%A1%A8%E6%A0%B9%20mm%20%E6%8C%87%E9%92%88%E5%85%B1%E4%BA%AB%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%85%B1%E4%BA%AB%EF%BC%88CLONE_VM%EF%BC%89%22%7C%20TH%5B%22%E5%90%8C%E7%BB%84%E7%BA%BF%E7%A8%8B%EF%BC%9A%E5%88%87%E6%8D%A2%E4%B8%8D%E6%8D%A2%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E5%85%B1%E4%BA%AB%22%7C%20PR%5B%22%E6%96%B0%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%EF%BC%9A%E7%8B%AC%E7%AB%8B%E8%BF%9B%E7%A8%8B%EF%BC%8C%E9%A1%B5%E5%86%99%E6%97%B6%E5%A4%8D%E5%88%B6%22%5D%0A%20%20TH%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E7%9C%BC%E9%87%8C%E9%83%BD%E6%98%AF%E5%90%84%E8%87%AA%E5%8F%AF%E8%B0%83%E5%BA%A6%E7%9A%84%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20PR%20--%3E%20SCHED%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<p><span class="marginnote">这张图回答「内核靠什么区分进程和线程」：答案是不区分类型，只看 <code>mm</code> 指针相不相同。初学者容易以为 Linux 里存在「线程对象」；实际上 pthread_create 底下就是一个带 <code>CLONE_VM|CLONE_FILES|CLONE_THREAD|CLONE_SIGHAND</code> 的 clone——「进程还是线程」是共享程度的描述，不是两种内核类型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 seccomp 与 clone 的组合写成攻击面，不讨论用户命名空间的全部能力下落。也不把 <code>clone3</code> 的结构体扩展当新哲学。FPU 与内核栈尚未单独成课：再下一课先把切换时那条内核栈钉死。</p><p>后课默认：创建用 clone 菜单。CPU 从一条任务换到另一条时保存什么、换什么，下一课讲<a href="/cs/context-switch">上下文切换</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>clone 用标志选择共享 mm、文件、信号等；线程是共享 vm 的一端。</li><li>每个 clone 仍是一个可调度 PCB。</li><li>如何把 CPU 交给另一条任务，下一课上下文切换。</li><li>出处：Love, <em>LKD</em>；Bovet and Cesati。</li></ul>',6))])}const L=s(A,[["render",i]]);export{D as __pageData,L as default};
